import React from 'react';
import Box from '@mui/material/Box';
import Paper from '@mui/material/Paper';
import Typography from '@mui/material/Typography';
import Button from '@mui/material/Button';
import FileDownloadIcon from '@mui/icons-material/FileDownload';

function NotesDisplay({ notes }) {
  // Function to parse and format the notes text
  const formatNotes = (text) => {
    // Split the text by lines
    const lines = text.split('\n').filter(line => line.trim() !== '');

    return lines.map((line, index) => {
      // Check if the line is a bullet point
      const isBullet = line.trim().startsWith('•') || line.trim().startsWith('-') || line.trim().startsWith('*');

      // If it's a bullet point, format it accordingly
      if (isBullet) {
        return (
          <div key={index} className="note-item note-item-bullet">
            {line.trim().substring(1).trim()}
          </div>
        );
      }

      // If it's a heading or regular text
      return (
        <div key={index} className="note-item">
          {line}
        </div>
      );
    });
  };

  const downloadNotes = () => {
    const element = document.createElement('a');
    const file = new Blob([notes], { type: 'text/plain' });
    element.href = URL.createObjectURL(file);
    element.download = 'youtube-notes.txt';
    document.body.appendChild(element);
    element.click();
    document.body.removeChild(element);
  };

  return (
    <Paper elevation={3} sx={{ p: 2, maxHeight: '500px', overflow: 'auto' }}>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
        <Typography variant="h6">
          Video Notes
        </Typography>
        <Button 
          variant="outlined" 
          size="small" 
          startIcon={<FileDownloadIcon />}
          onClick={downloadNotes}
        >
          Download
        </Button>
      </Box>
      <Box>
        {formatNotes(notes)}
      </Box>
    </Paper>
  );
}

export default NotesDisplay;
